ee:message.ee:set-payload:
%dw 2.0
output application/xml indent=false, writeDeclaration=false, skipNullOn="everywhere" 
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns wsse http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd
ns saml urn:oasis:names:tc:SAML:2.0:assertion
---
{
    soapenv#Envelope: {
    	soapenv#Header: {
			wsse#Security @(soapenv#mustUnderstand: "1") : {
            saml#Assertion @(ID: vars.samlResponse.Envelope.Body.RequestSecurityTokenResponseCollection.RequestSecurityTokenResponse.RequestedSecurityToken.Assertion.@ID , IssueInstant: vars.samlResponse.Envelope.Body.RequestSecurityTokenResponseCollection.RequestSecurityTokenResponse.RequestedSecurityToken.Assertion.@IssueInstant ,
Version: vars.samlResponse.Envelope.Body.RequestSecurityTokenResponseCollection.RequestSecurityTokenResponse.RequestedSecurityToken.Assertion.@Version): vars.samlResponse.Envelope.Body.RequestSecurityTokenResponseCollection.RequestSecurityTokenResponse.RequestedSecurityToken.Assertion
            }
        },
        soapenv#Body: {
            ExternalPrimaryAccountRequest @(xmlns: "http://www.westfieldgrp.com/billing"): 
            	{
                    policyNumber: vars.params.policyNumber,
               		accountNumber: vars.params.billingAccountNumber,
               		accountFeatures : "PastDue"
               	}
         }

       }
}

